CREATE TABLE schema_version (id BIGINT PRIMARY KEY NOT NULL, version BIGINT NOT NULL);
INSERT INTO schema_version VALUES (0, 6);
CREATE TABLE games (
    id TEXT COLLATE "C" PRIMARY KEY NOT NULL, black TEXT NOT NULL, white TEXT NOT NULL,
    version BIGINT NOT NULL CHECK(version >= 0), winner INTEGER, reason INTEGER,
    rule TEXT NOT NULL CHECK(rule = 'standard'),
    visibility TEXT NOT NULL CHECK(visibility IN ('public', 'private')),
    finished_at BIGINT CHECK(finished_at IS NULL OR finished_at >= 0),
    final_move_ply BIGINT NOT NULL CHECK(final_move_ply >= 0),
    CHECK(black != white),
    CHECK((winner IS NULL AND reason IS NULL AND finished_at IS NULL) OR
        (winner IS NOT NULL AND reason IS NOT NULL AND finished_at IS NOT NULL
         AND winner IN (1,2) AND reason IN (1,2)))
);
CREATE TABLE journal (
    game_id TEXT NOT NULL REFERENCES games(id), seq BIGINT NOT NULL CHECK(seq > 0),
    request_id TEXT NOT NULL, user_id TEXT NOT NULL,
    expected_seq BIGINT NOT NULL CHECK(expected_seq >= 0), action INTEGER NOT NULL,
    usi TEXT, in_check BOOLEAN NOT NULL, winner INTEGER, reason INTEGER,
    PRIMARY KEY(game_id, seq), UNIQUE(game_id, request_id),
    CHECK(expected_seq = seq - 1),
    CHECK((action = 1 AND usi IS NOT NULL) OR (action = 2 AND usi IS NULL)),
    CHECK((winner IS NULL AND reason IS NULL) OR
        (winner IS NOT NULL AND reason IS NOT NULL AND winner IN (1,2) AND reason IN (1,2)))
);
CREATE TABLE outbox_events (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, game_id TEXT NOT NULL, seq BIGINT NOT NULL,
    event_kind INTEGER NOT NULL CHECK(event_kind IN (0,1)), encoding_version INTEGER NOT NULL,
    request_id TEXT NOT NULL, user_id TEXT NOT NULL, usi TEXT, in_check BOOLEAN,
    winner INTEGER, reason INTEGER,
    published BOOLEAN NOT NULL DEFAULT FALSE,
    UNIQUE(game_id, seq, event_kind),
    FOREIGN KEY(game_id, seq) REFERENCES journal(game_id, seq),
    CHECK((winner IS NULL AND reason IS NULL) OR
        (winner IS NOT NULL AND reason IS NOT NULL AND winner IN (1,2) AND reason IN (1,2))),
    CHECK((event_kind = 0 AND usi IS NOT NULL AND in_check IS NOT NULL
            AND (reason IS NULL OR reason = 1))
        OR (event_kind = 1 AND usi IS NULL AND in_check IS NULL AND winner IS NOT NULL))
);
CREATE INDEX outbox_pending ON outbox_events(published, id);
CREATE INDEX records_finished ON games(finished_at DESC, id COLLATE "C" DESC) WHERE visibility = 'public' AND finished_at IS NOT NULL;
CREATE INDEX records_black ON games(black, finished_at DESC, id COLLATE "C" DESC) WHERE visibility = 'public' AND finished_at IS NOT NULL;
CREATE INDEX records_white ON games(white, finished_at DESC, id COLLATE "C" DESC) WHERE visibility = 'public' AND finished_at IS NOT NULL;

CREATE TABLE "rating_states" ( "user_id" text NOT NULL, "pool" text NOT NULL CHECK ("pool" IN ('ten_minute_30', 'byoyomi_30')), "rating" bigint, "completed" bigint NOT NULL, PRIMARY KEY ("user_id", "pool"), CHECK (("rating" IS NULL AND "completed" = 0) OR ("rating" IS NOT NULL AND "completed" > 0)) );
CREATE TABLE "rated_games" ( "game_id" text NOT NULL PRIMARY KEY, "pool" text NOT NULL CHECK ("pool" IN ('ten_minute_30', 'byoyomi_30')), "black_start_rating" bigint, "black_start_count" bigint NOT NULL, "white_start_rating" bigint, "white_start_count" bigint NOT NULL, FOREIGN KEY ("game_id") REFERENCES "games" ("id"), CHECK (("black_start_rating" IS NULL AND "black_start_count" = 0) OR ("black_start_rating" IS NOT NULL AND "black_start_count" > 0)), CHECK (("white_start_rating" IS NULL AND "white_start_count" = 0) OR ("white_start_rating" IS NOT NULL AND "white_start_count" > 0)) );
CREATE TABLE "rating_slots" ( "user_id" text NOT NULL, "pool" text NOT NULL CHECK ("pool" IN ('ten_minute_30', 'byoyomi_30')), "game_id" text NOT NULL, PRIMARY KEY ("user_id", "pool"), FOREIGN KEY ("user_id", "pool") REFERENCES "rating_states" ("user_id", "pool"), FOREIGN KEY ("game_id") REFERENCES "rated_games" ("game_id") );
CREATE TABLE "rating_jobs" ( "game_id" text NOT NULL PRIMARY KEY, "state" text NOT NULL CHECK ("state" IN ('pending', 'claimed', 'quarantined', 'completed')), "owner" text, "generation" bigint NOT NULL CHECK ("generation" >= 0), "lease_until" bigint, "available_at" bigint NOT NULL, "attempts" bigint NOT NULL CHECK ("attempts" >= 0), "last_error" text, FOREIGN KEY ("game_id") REFERENCES "rated_games" ("game_id"), CHECK (("state" = 'claimed' AND "owner" IS NOT NULL AND "lease_until" IS NOT NULL) OR ("state" <> 'claimed' AND "owner" IS NULL AND "lease_until" IS NULL)) );
CREATE TABLE "rating_applications" ( "game_id" text NOT NULL PRIMARY KEY, "pool" text NOT NULL CHECK ("pool" IN ('ten_minute_30', 'byoyomi_30')), "final_seq" bigint NOT NULL CHECK ("final_seq" > 0), "delta_black" bigint NOT NULL CHECK ("delta_black" BETWEEN -32 AND 32), "black_before_rating" bigint, "black_before_count" bigint NOT NULL, "white_before_rating" bigint, "white_before_count" bigint NOT NULL, "black_after_rating" bigint NOT NULL, "black_after_count" bigint NOT NULL CHECK ("black_after_count" > 0), "white_after_rating" bigint NOT NULL, "white_after_count" bigint NOT NULL CHECK ("white_after_count" > 0), FOREIGN KEY ("game_id") REFERENCES "rating_jobs" ("game_id"), CHECK (("black_before_rating" IS NULL AND "black_before_count" = 0) OR ("black_before_rating" IS NOT NULL AND "black_before_count" > 0)), CHECK (("white_before_rating" IS NULL AND "white_before_count" = 0) OR ("white_before_rating" IS NOT NULL AND "white_before_count" > 0)) );
CREATE INDEX "rating_jobs_pending" ON "rating_jobs" ("state", "available_at", "game_id");
CREATE INDEX "rating_jobs_expired" ON "rating_jobs" ("state", "lease_until", "game_id");
